class Subsession(BaseSubsession):
    pass


class Group(BaseGroup):
    pass


class Player(BasePlayer):

    # number of sliders completed - this is for determining payment
    num_sliders = models.IntegerField(initial=0)
    # number of times the keyboard is used while slider has focus - parameter of interest
    num_keystrokes = models.IntegerField(initial=0)


# PAGES
class Sliders(Page):
    timeout_seconds = Constants.time_in_seconds

    form_model = 'player'
    form_fields = ['num_sliders', 'num_keystrokes']

    @staticmethod
    def vars_for_template(player: Player):
        slider_list = []
        for i, X in enumerate(Constants.slider_xs):
            slider_list.append([i, X, Constants.slider_ys[i]])
        return dict(slider_list=slider_list)



class Results(Page):
    pass


page_sequence = [Sliders, Results]
